def find_connected_regions(grid):
    """Find all connected regions of each color."""
    rows, cols = len(grid), len(grid[0])
    regions = {}
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if (r, c) not in visited:
                color = grid[r][c]
                region = set()
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited or grid[cr][cc] != color:
                        continue
                    visited.add((cr, cc))
                    region.add((cr, cc))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in visited:
                            stack.append((nr, nc))
                regions[color] = regions.get(color, []) + [region]

    return regions

def is_rectangular_region(cells):
    """Check if a set of cells forms a perfect rectangle."""
    if not cells:
        return False
    min_r, min_c = float('inf'), float('inf')
    max_r, max_c = float('-inf'), float('-inf')

    for (r, c) in cells:
        min_r = min(min_r, r)
        min_c = min(min_c, c)
        max_r = max(max_r, r)
        max_c = max(max_c, c)

    expected_count = (max_r - min_r + 1) * (max_c - min_c + 1)
    return len(cells) == expected_count

