"""
Fix the connected regions algorithm - use BFS properly.
"""

def find_connected_regions(grid):
    """Find all connected regions of each color using BFS."""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    regions = {}

    for r in range(rows):
        for c in range(cols):
            if (r, c) in visited:
                continue
            color = grid[r][c]
            from collections import deque
            region = []
            queue = deque([(r, c)])

            while queue:
                cur_r, cur_c = queue.popleft()
                if (cur_r, cur_c) in visited:
                    continue
                visited.add((cur_r, cur_c))
                region.append((cur_r, cur_c))

                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cur_r + dr, cur_c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in visited:
                        queue.append((nr, nc))

            if len(region) > 1:  # Only record multi-cell regions
                regions.setdefault(color, []).append(region)

    return regions

